draw:
var E1 = p.emf1, E2 = p.emf2, R = p.res;
var I = (E1 - E2) / R;

var pad = Math.min(W, H) * 0.16;
var x0 = pad, x1 = W - pad, y0 = pad, y1 = H - pad * 0.9;

ctx.lineWidth = 2;
ctx.strokeStyle = C.rule;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// the loop, drawn as four sides with gaps for the components
// top side: battery 1 (gap in the middle)
var midT = (x0 + x1) / 2;
ctx.beginPath();
ctx.moveTo(x0, y0); ctx.lineTo(midT - 14, y0);
ctx.moveTo(midT + 14, y0); ctx.lineTo(x1, y0);
ctx.stroke();

// right side: resistor zigzag in the middle
var midR = (y0 + y1) / 2;
ctx.beginPath();
ctx.moveTo(x1, y0); ctx.lineTo(x1, midR - 24);
ctx.moveTo(x1, midR + 24); ctx.lineTo(x1, y1);
ctx.stroke();

// bottom side: battery 2 (gap in the middle)
ctx.beginPath();
ctx.moveTo(x1, y1); ctx.lineTo(midT + 14, y1);
ctx.moveTo(midT - 14, y1); ctx.lineTo(x0, y1);
ctx.stroke();

// left side: plain wire
ctx.beginPath();
ctx.moveTo(x0, y1); ctx.lineTo(x0, y0);
ctx.stroke();

// battery symbol helper (horizontal), plus plate on the +x side
function battH(cx, cy, flip) {
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cx - 5 * flip, cy - 11); ctx.lineTo(cx - 5 * flip, cy + 11);
  ctx.stroke();
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(cx + 5 * flip, cy - 6); ctx.lineTo(cx + 5 * flip, cy + 6);
  ctx.stroke();
  ctx.lineWidth = 2;
}

// battery 1 on top: long (positive) plate on the left, so it drives current
// anticlockwise round the picture, i.e. down the left wire
battH(midT, y0, -1);
ctx.fillStyle = C.ink;
ctx.fillText("E1 = " + E1.toFixed(1) + " V", midT, y0 - 14);

// battery 2 on the bottom, opposing
battH(midT, y1, 1);
ctx.fillText("E2 = " + E2.toFixed(1) + " V", midT, y1 + 22);

// resistor on the right
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x1, midR - 24);
var k;
for (k = 0; k < 6; k++) {
  ctx.lineTo(x1 + (k % 2 === 0 ? 9 : -9), midR - 24 + 8 * (k + 0.5));
}
ctx.lineTo(x1, midR + 24);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("R = " + R.toFixed(1) + " ohm", x1 + 14, midR + 4);
ctx.textAlign = "center";

// moving charge dots: anticlockwise when I is positive
var per = Math.max(0.12, Math.abs(I)) * 0.5;
var phase = (t * per) % 1;
var dir = I >= 0 ? 1 : -1;
var Lx = x1 - x0, Ly = y1 - y0;
var per2 = 2 * (Lx + Ly);
var n;
ctx.fillStyle = C.accent;
for (n = 0; n < 12; n++) {
  var s = (((n / 12 + dir * phase) % 1) + 1) % 1;
  var d = s * per2;
  var px, py;
  if (d < Ly) { px = x0; py = y0 + d; }
  else if (d < Ly + Lx) { px = x0 + (d - Ly); py = y1; }
  else if (d < 2 * Ly + Lx) { px = x1; py = y1 - (d - Ly - Lx); }
  else { px = x1 - (d - 2 * Ly - Lx); py = y0; }
  ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI * 2); ctx.fill();
}

// loop-walk arrow in the middle
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.arc(W / 2, (y0 + y1) / 2, Math.min(Lx, Ly) * 0.22, 0.4, 5.2);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("walk this way", W / 2, (y0 + y1) / 2 + 4);

out.note = "I = (" + E1.toFixed(1) + " - " + E2.toFixed(1) + ") / " + R.toFixed(1) +
  " = " + I.toFixed(3) + " A" + (I < 0 ? "  (runs the other way)" : "") +
  ",  drop across R = " + (I * R).toFixed(2) + " V";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;
ctx.textAlign = "center";

var colY = [H * 0.30, H * 0.72];
var colX = [W * 0.26, W * 0.74];

function arrowTo(ax, ay, bx, by) {
  ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
  var a = Math.atan2(by - ay, bx - ax);
  ctx.beginPath();
  ctx.moveTo(bx, by);
  ctx.lineTo(bx - 7 * Math.cos(a - 0.4), by - 7 * Math.sin(a - 0.4));
  ctx.lineTo(bx - 7 * Math.cos(a + 0.4), by - 7 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

function resistor(cx, cy, w) {
  ctx.strokeStyle = C.figure;
  ctx.beginPath();
  ctx.moveTo(cx - w, cy);
  var k;
  for (k = 0; k < 6; k++) ctx.lineTo(cx - w + (w * 2 / 6) * (k + 0.5), cy + (k % 2 === 0 ? -8 : 8));
  ctx.lineTo(cx + w, cy);
  ctx.stroke();
}

function battery(cx, cy, plusLeft) {
  ctx.strokeStyle = C.ink;
  var s = plusLeft ? -1 : 1;
  ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(cx + 5 * s, cy - 10); ctx.lineTo(cx + 5 * s, cy + 10); ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(cx - 5 * s, cy - 6); ctx.lineTo(cx - 5 * s, cy + 6); ctx.stroke();
}

var i, j;
for (j = 0; j < 2; j++) {
  for (i = 0; i < 2; i++) {
    var cx = colX[i], cy = colY[j], w = Math.min(W * 0.16, 54);
    // lead wires
    ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx - w - 26, cy); ctx.lineTo(cx - w, cy);
    ctx.moveTo(cx + w, cy); ctx.lineTo(cx + w + 26, cy);
    ctx.stroke();

    if (j === 0) resistor(cx, cy, w); else battery(cx, cy, i === 1);

    // walking arrow, always left to right
    ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent; ctx.lineWidth = 1.5;
    arrowTo(cx - w - 24, cy - 26, cx - w + 6, cy - 26);
    ctx.fillText("walk", cx - w - 9, cy - 32);
  }
}

// current arrows on the resistor row
ctx.strokeStyle = C.ink; ctx.fillStyle = C.ink; ctx.lineWidth = 1.5;
arrowTo(colX[0] - 10, colY[0] + 26, colX[0] + 24, colY[0] + 26);
arrowTo(colX[1] + 24, colY[0] + 26, colX[1] - 10, colY[0] + 26);
ctx.fillText("I", colX[0] + 7, colY[0] + 42);
ctx.fillText("I", colX[1] + 7, colY[0] + 42);

// labels
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.fillText("resistor, walking with the current", colX[0], colY[0] - 46);
ctx.fillText("term is  -IR", colX[0], colY[0] + 62);
ctx.fillText("resistor, walking against it", colX[1], colY[0] - 46);
ctx.fillText("term is  +IR", colX[1], colY[0] + 62);
ctx.fillText("battery, minus plate first", colX[0], colY[1] - 46);
ctx.fillText("term is  +E", colX[0], colY[1] + 40);
ctx.fillText("battery, plus plate first", colX[1], colY[1] - 46);
ctx.fillText("term is  -E", colX[1], colY[1] + 40);

// plate signs
ctx.fillStyle = C.figure;
ctx.fillText("-", colX[0] - 14, colY[1] - 16);
ctx.fillText("+", colX[0] + 16, colY[1] - 16);
ctx.fillText("+", colX[1] - 14, colY[1] - 16);
ctx.fillText("-", colX[1] + 16, colY[1] - 16);

out.note = "add the four kinds of term round a loop and set the total to zero";

var V = 6.0;
var R1 = p.r1, R2 = 200, R3 = 150, R4 = p.r4, Rg = p.rg;

// node equations at A and B, with the source node at V and ground at 0
var a11 = 1 / R1 + 1 / R2 + 1 / Rg;
var a12 = -1 / Rg;
var a21 = -1 / Rg;
var a22 = 1 / R3 + 1 / R4 + 1 / Rg;
var b1 = V / R1, b2 = V / R3;
var det = a11 * a22 - a12 * a21;
var VA = (b1 * a22 - a12 * b2) / det;
var VB = (a11 * b2 - a21 * b1) / det;
var Ig = (VA - VB) / Rg;

var pad = Math.min(W, H) * 0.14;
var xS = W * 0.16, xM = W * 0.5, xG = W * 0.84;
var yA = H * 0.30, yB = H * 0.70, yMid = H * 0.5;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
ctx.lineWidth = 2;

function seg(ax, ay, bx, by) {
  ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
}

function box(cx, cy, label, col) {
  ctx.fillStyle = C.paper;
  ctx.fillRect(cx - 20, cy - 9, 40, 18);
  ctx.strokeStyle = col; ctx.lineWidth = 2;
  ctx.strokeRect(cx - 20, cy - 9, 40, 18);
  ctx.fillStyle = col;
  ctx.fillText(label, cx, cy + 4);
}

// wires
ctx.strokeStyle = C.rule;
seg(xS, yMid, xS, yA); seg(xS, yA, xM, yA); seg(xM, yA, xG, yA); seg(xG, yA, xG, yMid);
seg(xS, yMid, xS, yB); seg(xS, yB, xM, yB); seg(xM, yB, xG, yB); seg(xG, yB, xG, yMid);
seg(xM, yA, xM, yB);

// components
box((xS + xM) / 2, yA, R1.toFixed(0), C.figure);
box((xM + xG) / 2, yA, R2.toFixed(0), C.figure);
box((xS + xM) / 2, yB, R3.toFixed(0), C.figure);
box((xM + xG) / 2, yB, R4.toFixed(0), C.figure);

// galvanometer in the bridge arm
ctx.fillStyle = C.paper;
ctx.beginPath(); ctx.arc(xM, yMid, 14, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(xM, yMid, 14, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("G", xM, yMid + 4);

// node dots and names
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(xM, yA, 4, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(xM, yB, 4, 0, Math.PI * 2); ctx.fill();
ctx.fillText("A", xM + 16, yA - 8);
ctx.fillText("B", xM + 16, yB + 18);
ctx.fillText("S  " + V.toFixed(1) + " V", xS, yMid - 22);
ctx.fillText("G  0 V", xG, yMid + 30);
ctx.fillStyle = C.faint;
ctx.fillText("VA = " + VA.toFixed(2) + " V", xM - 52, yA - 22);
ctx.fillText("VB = " + VB.toFixed(2) + " V", xM - 52, yB + 32);

// source terminals
ctx.strokeStyle = C.ink; ctx.lineWidth = 4;
ctx.beginPath(); ctx.moveTo(xS - 9, yMid - 6); ctx.lineTo(xS + 9, yMid - 6); ctx.stroke();
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(xS - 5, yMid + 4); ctx.lineTo(xS + 5, yMid + 4); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xG - 12, yMid); ctx.lineTo(xG + 12, yMid); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xG - 8, yMid + 5); ctx.lineTo(xG + 8, yMid + 5); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xG - 4, yMid + 10); ctx.lineTo(xG + 4, yMid + 10); ctx.stroke();

// current in the bridge arm, animated dots along A-B
var mag = Math.min(1, Math.abs(Ig) / 0.004);
var dir = Ig >= 0 ? 1 : -1;
var k;
ctx.fillStyle = C.accent;
for (k = 0; k < 5; k++) {
  var s = ((k / 5 + dir * (t * (0.15 + mag)) % 1) + 1) % 1;
  var py = yA + s * (yB - yA);
  if (Math.abs(py - yMid) < 16) continue;
  ctx.beginPath(); ctx.arc(xM, py, 3, 0, Math.PI * 2); ctx.fill();
}

var bal = R1 * R4 - R2 * R3;
out.note = "VA - VB = " + (VA - VB).toFixed(3) + " V,  galvanometer current = " +
  (Ig * 1000).toFixed(3) + " mA.  R1*R4 - R2*R3 = " + bal.toFixed(0) +
  (Math.abs(bal) < 1 ? "  (balanced)" : "");
